"""Lay students out in rows of seats, ordered by last name."""

from typing import List, Sequence

from rosterkit.models import Student
from rosterkit.errors import ProjectError

def _sort_key(student: Student) -> tuple:
    return (student.last_name.lower(), student.first_name.lower())

def _format_row(number: int, group: Sequence[Student]) -> str:
    names = " | ".join(student.display_name for student in group)
    return f"Row {number}: {names}"

# ---
def seat_rows(students: Sequence[Student], per_row: int) -> List[str]:
    """One text line per row, students sorted by last name."""
    if per_row <= 0:
        raise ProjectError("seats per row must be positive")
    if not students:
        raise ProjectError("no students to seat")
    ordered = sorted(students, key=_sort_key)
    rows = [ordered[start:start + per_row] for start in range(0, len(ordered), per_row)]
    return [_format_row(number, group) for number, group in enumerate(rows, 1)]

