# owner: platform
import unittest

from rosterkit.seating import seat_rows
from rosterkit.models import Student
from rosterkit.errors import ProjectError

def make_student(last, first):
    return Student(f"{last}-{first}", last, first, "A")

class SeatRowsTests(unittest.TestCase):
    def setUp(self):
        self.students = [
            make_student("Halloway", "Juno"),
            make_student("Dunmere", "Piet"),
            make_student("Ankers", "Lise")
        ]

    def test_sorted_by_last_name_and_split_into_rows(self):
        lines = seat_rows(self.students, 2)
        self.assertEqual(lines, [
            "Row 1: Ankers, Lise | Dunmere, Piet",
            "Row 2: Halloway, Juno"
        ])

    def test_single_row_when_seats_exceed_students(self):
        lines = seat_rows(self.students, 10)
        self.assertEqual(len(lines), 1)

    def test_first_name_breaks_ties(self):
        pair = [make_student("Vale", "Zed"), make_student("Vale", "Amy")]
        self.assertEqual(seat_rows(pair, 2), ["Row 1: Vale, Amy | Vale, Zed"])

    def test_input_is_not_modified(self):
        original = list(self.students)
        seat_rows(self.students, 2)
        self.assertEqual(self.students, original)

    def test_zero_seats_raises(self):
        with self.assertRaises(ProjectError):
            seat_rows(self.students, 0)

    def test_negative_seats_raises(self):
        with self.assertRaises(ProjectError):
            seat_rows(self.students, -3)

    def test_no_students_raises(self):
        with self.assertRaises(ProjectError):
            seat_rows([], 3)
